                                <div style="text-align:center;margin-left: 250px">
                                    <h1 style="font-size: 28px;">教师账号注册</h1>
                                </div>
                                <el-col :span="12" :offset="6">
                                    <div class="body_form">
                                        <el-form label-position="right" :model="teacherForm" ref="teacherForm"
