                                </div>
                                <div style="float: right">
                                    <el-upload :action="uploadAction_student" style="display: inline-block;"
                                               :show-file-list="false" :on-success="successUpload">
                                        <el-button
                                                type="primary"
                                                size="medium"
                                                icon="el-icon-upload2"
                                                style="margin-right: 20px;border-radius: 20px"
                                        >批量导入
                                        </el-button>
                                    </el-upload>
                                </div>
                                <div style="text-align:center;margin-left: 250px">
                                    <h1 style="font-size: 28px;">学生账号注册</h1>
                                </div>
                                <el-col :span="12" :offset="6">
                                    <div class="body_form">
                                        <el-form label-position="right" :model="studentForm" ref="studentForm"
                                                 :rules="rules">
                                            <el-form-item label="院系名称" prop="college_studentNickname">
                                                <el-select v-model="studentForm.college_studentNickname"
                                                           placeholder="请选择">
                                                    <el-option v-for="college in tableData" :key="college.id"
                                                               :label="college.nickname" :value="college.id">
                                                    </el-option>
                                                </el-select>
                                            </el-form-item>
                                            <el-form-item label="学生名称" prop="studentNickname">
                                                <el-input v-model="studentForm.studentNickname"
                                                          autocomplete="off"></el-input>
                                            </el-form-item>
                                            <el-form-item label="登录密码" prop="studentPassword">
                                                <el-input type="password" v-model="studentForm.studentPassword"
                                                          autocomplete="off"></el-input>
                                            </el-form-item>
                                            <el-form-item label="重新输入密码" prop="studentRePassword">
                                                <el-input type="password" v-model="studentForm.studentRePassword"
                                                          autocomplete="off"></el-input>
                                            </el-form-item>
                                        </el-form>
                                        <div slot="footer" class="dialog-footer" style="float: right">
                                            <el-tooltip class="item" effect="dark" style="margin-left: 50px"
                                                        content="重置信息" placement="right">
                                                <el-button type="warning" icon="el-icon-refresh-left" circle
                                                           @click="resetForm('studentForm')"></el-button>
                                            </el-tooltip>
                                            <el-button type="primary" icon="el-icon-edit-outline"
                                                       @click="submitStudent('studentForm')" round>注册
                                            </el-button>
                                        </div>
                                    </div>
                                </el-col>
                            </div>
                        </el-card>
                    </el-tab-pane>
                    <!--学生账号弹出框-->
                    <el-drawer
                            title="学生账号信息"
                            :visible.sync="drawer_student"
                            :direction="direction">
                        <el-table
                                ref="table_student"
                                :data="tableData_student"
                                stripe
                                style="width: 100%"
                                :header-cell-style="{ 'text-align': 'center' }">
                            <el-table-column
                                    type="selection"
                                    align="center"
                                    width="50">
                            </el-table-column>
                            <el-table-column
                                    prop="collegeName"
                                    label="院系名称"
                                    align="center"
                                    width="200">
                            </el-table-column>
                            <el-table-column
                                    prop="nickname"
                                    label="学生"
                                    align="center"
                                    width="">
                            </el-table-column>
                            <el-table-column
                                    prop="username"
                                    label="账号"
                                    align="center"
                                    width="">
                            </el-table-column>
                            <el-table-column
                                    prop="password"
                                    align="center"
                                    label="密码">
                            </el-table-column>
                        </el-table>
                        <div style="text-align:right; margin-top: 20px;margin-right: 20px;float: right">
                            <el-button type="danger" size="medium" icon="el-icon-delete" style="border-radius: 20px"
                                       @click="handleDelete_student">删除
                            </el-button>
                        </div>
                        <div style="text-align:right; margin-top: 20px;margin-right: 20px;float: right">
                            <el-button type="success" size="medium" icon="el-icon-download" style="border-radius: 20px"
                                       @click="handleExp_student">导出
                            </el-button>
                        </div>
                    </el-drawer>
                </el-tabs>
            </div>
