</template>
<script>
    import api from '../../main.js'

    export default {
        inject: ['reload'],
        name: "admin_home",
        data() {
            var validatePass = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入密码'));
                } else {
                    if (this.checkUser.rePassword !== '') {
                        this.$refs.checkUser.validateField('rePassword');
                    }
                    callback();
                }
            };
            var validatePass2 = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请再次输入密码'));
                } else if (value !== this.checkUser.password) {
                    callback(new Error('两次输入密码不一致!'));
                } else {
                    callback();
                }
            };
            var validateCollegePass = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入密码'));
                } else {
                    if (this.collegeForm.collegeRePassword !== '') {
                        this.$refs.collegeForm.validateField('collegeRePassword');
                    }
                    callback();
                }
            };
            var validateCollegePass2 = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请再次输入密码'));
                } else if (value !== this.collegeForm.collegePassword) {
                    callback(new Error('两次输入密码不一致!'));
                } else {
                    callback();
                }
            };
            var validateTeacherPass = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入密码'));
                } else {
                    if (this.teacherForm.teacherRePassword !== '') {
                        this.$refs.teacherForm.validateField('teacherRePassword');
                    }
                    callback();
                }
            };
            var validateTeacherPass2 = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请再次输入密码'));
                } else if (value !== this.teacherForm.teacherPassword) {
                    callback(new Error('两次输入密码不一致!'));
                } else {
                    callback();
                }
            };
            var validateStudentPass = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入密码'));
                } else {
                    if (this.studentForm.studentRePassword !== '') {
                        this.$refs.studentForm.validateField('studentRePassword');
                    }
                    callback();
                }
            };
            var validateStudentPass2 = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请再次输入密码'));
                } else if (value !== this.studentForm.studentPassword) {
                    callback(new Error('两次输入密码不一致!'));
                } else {
                    callback();
                }
            };
            return {
                userData: {},
                tableData: [],
                tableData_table: [],
                tableData_student: [],
                table_teacher: [],
                table_student: [],
                collegeOptions: [], // 存储学院账号信息中的 nickname 列表
                uploadAction: api + '/admin/createAllCollege',
                uploadAction_teacher: api + '/admin/createAllTeacher',
                uploadAction_student: api + '/admin/createAllStudent',
                drawer: false,
                drawer_teacher: false,
                drawer_student: false,
                direction: 'rtl',
                collegeForm: {
                    collegeNickname: '',
                    collegePassword: '',
                    collegeRePassword: ''
                },
                teacherForm: {
                    college_teacherNickname: '',
                    teacherNickname: '',
                    teacherPassword: '',
                    teacherRePassword: ''
                },
                studentForm: {
                    college_studentNickname: '',
                    studentNickname: '',
                    studentPassword: '',
                    studentRePassword: ''
                },
                checkUser: {
                    nickname: "",
                    password: '',
                    rePassword: ''
                },
                showTable: true,
                dialogFormVisible: false,
                activeName: "个人信息管理",
                labelPosition: 'right',
                dialogWidth: '700px',
                labelWidth: '120px',
                rules: {
                    password: [
                        {validator: validatePass, trigger: 'blur'}
                    ],
                    rePassword: [
                        {validator: validatePass2, trigger: 'blur'}
                    ],
                    nickname: [
                        {required: true, message: '昵称（姓名）不可为空', trigger: 'blur'}
                    ],
                    collegeNickname: [
                        {required: true, message: '学院名称不可为空', trigger: 'blur'}
                    ],
                    collegePassword: [
                        {validator: validateCollegePass, trigger: 'blur'}
                    ],
                    collegeRePassword: [
                        {validator: validateCollegePass2, trigger: 'blur'}
                    ],
                    college_teacherNickname: [
                        {required: true, message: '学院名称不可为空', trigger: 'blur'}
                    ],
                    teacherNickname: [
                        {required: true, message: '教师名称不可为空', trigger: 'blur'}
                    ],
                    teacherPassword: [
                        {validator: validateTeacherPass, trigger: 'blur'}
                    ],
                    teacherRePassword: [
                        {validator: validateTeacherPass2, trigger: 'blur'}
                    ],
                    college_studentNickname: [
                        {required: true, message: '学院名称不可为空', trigger: 'blur'}
                    ],
                    studentNickname: [
                        {required: true, message: '学生名称不可为空', trigger: 'blur'}
                    ],
                    studentPassword: [
                        {validator: validateStudentPass, trigger: 'blur'}
                    ],
                    studentRePassword: [
                        {validator: validateStudentPass2, trigger: 'blur'}
                    ],
                }
            };

        },
        created() {
            this.getCollgeData();
            this.getTeacherData();
            this.getStudentData();
        },
        mounted() {
            this.getUserData();
            this.getCollgeData();
            this.getTeacherData();
            this.getStudentData();
        },
        methods: {
            handleClick(tab, event) {
            },
            handleDrawer() {
                // 调用获取表格数据的接口
                this.getCollgeData();
                // 打开抽屉
                this.drawer = true;
            },
            handleDrawer_teacher() {
                // 调用获取表格数据的接口
                this.getTeacherData();
                // 打开抽屉
                this.drawer_teacher = true;
            },
            handleDrawer_student() {
                // 调用获取表格数据的接口
                this.getStudentData();
                // 打开抽屉
                this.drawer_student = true;
            },
            handleExp() {
                // 调用导出函数
                this.exportExcel(this.tableData, '学院账号信息');
            },
            exportExcel(tableData, fileName) {
                // 创建一个新的 Excel 实例
                let excel = [];
                // 添加 Excel 表头
                let header = ['院系名称', '账号', '密码'];
                excel.push(header);
                // 添加表格数据
                tableData.forEach(row => {
                    let rowData = [row.nickname, row.username, row.password];
                    excel.push(rowData);
                });
                // 创建 Excel 文件
                let wb = this.XLSX.utils.book_new();
                wb.Props = {
                    Title: fileName,
                    Subject: '',
                    Author: '',
                    CreatedDate: new Date()
                };
                let ws = this.XLSX.utils.aoa_to_sheet(excel);
                this.XLSX.utils.book_append_sheet(wb, ws, fileName);
                // 将 Excel 文件转换为二进制数据流
                let wbout = this.XLSX.write(wb, {bookType: 'xlsx', type: 'array'});
                // 创建 Blob 对象
                let blob = new Blob([wbout], {type: 'application/octet-stream'});
                // 下载 Excel 文件
                let filename = fileName + '.xlsx';
                if (window.navigator.msSaveOrOpenBlob) {
                    window.navigator.msSaveOrOpenBlob(blob, filename);
                } else {
                    let link = document.createElement('a');
                    link.href = window.URL.createObjectURL(blob);
                    link.download = filename;
                    link.click();
                }
            },
            handleExp_teacher() {
                // 调用导出函数
                this.exportExcel_teacher(this.tableData_table, '教师账号信息');
            },
            exportExcel_teacher(tableData_table, fileName) {
                // 创建一个新的 Excel 实例
                let excel = [];
                // 添加 Excel 表头
                let header = ['院系名称', '教师姓名', '账号', '密码'];
                excel.push(header);
                // 添加表格数据
                tableData_table.forEach(row => {
